const alert = items[0].json;

// Extract fields from Wazuh/Splunk alert format
const result = {
  timestamp: alert['@timestamp'] || alert.timestamp || new Date().toISOString(),
  agent: {
    name: alert.agent?.name || alert['agent.name'] || 'Unknown',
    id: alert.agent?.id || alert['agent.id'] || '000',
    ip: alert.agent?.ip || alert['agent.ip'] || '0.0.0.0'
  },
  rule: {
    id: alert.rule?.id || alert['rule.id'] || '0',
    level: alert.rule?.level || alert['rule.level'] || 0,
    description: alert.rule?.description || alert['rule.description'] || 'No description',
    groups: alert.rule?.groups || alert['rule.groups'] || [],
    mitre: alert.rule?.mitre?.id || alert['rule.mitre.id'] || []
  },
  winlog: {
    event_id: alert.winlog?.event_id || alert['winlog.event_id'] || 0,
    channel: alert.winlog?.channel || alert['winlog.channel'] || '',
    provider: alert.winlog?.provider_name || alert['winlog.provider_name'] || ''
  },
  process: {
    name: alert.win?.eventdata?.image || alert['win.eventdata.image'] || '',
    pid: alert.win?.eventdata?.processid || alert['win.eventdata.processid'] || 0,
    commandline: alert.win?.eventdata?.commandline || alert['win.eventdata.commandline'] || '',
    parent_name: alert.win?.eventdata?.parentimage || alert['win.eventdata.parentimage'] || '',
    parent_pid: alert.win?.eventdata?.parentprocessid || alert['win.eventdata.parentprocessid'] || 0
  },
  target: {
    image: alert.win?.eventdata?.targetimage || alert['win.eventdata.targetimage'] || '',
    pid: alert.win?.eventdata?.targetprocessid || alert['win.eventdata.targetprocessid'] || 0,
    granted_access: alert.win?.eventdata?.grantedaccess || alert['win.eventdata.grantedaccess'] || ''
  },
  file: {
    hash_sha256: alert.win?.eventdata?.hashes?.sha256 || alert['win.eventdata.hashes.sha256'] || alert.win?.eventdata?.hash || alert['win.eventdata.hash'] || '',
    path: alert.win?.eventdata?.targetfilename || alert['win.eventdata.targetfilename'] || alert.win?.eventdata?.image || alert['win.eventdata.image'] || '',
    size: alert.win?.eventdata?.size || alert['win.eventdata.size'] || 0
  },
  network: {
    protocol: alert.win?.eventdata?.protocol || alert['win.eventdata.protocol'] || '',
    src_ip: alert.win?.eventdata?.sourceip || alert['win.eventdata.sourceip'] || '',
    src_port: alert.win?.eventdata?.sourceport || alert['win.eventdata.sourceport'] || 0,
    dst_ip: alert.win?.eventdata?.destinationip || alert['win.eventdata.destinationip'] || '',
    dst_port: alert.win?.eventdata?.destinationport || alert['win.eventdata.destinationport'] || 0
  },
  user: {
    name: alert.win?.eventdata?.user || alert['win.eventdata.user'] || '',
    domain: alert.win?.eventdata?.domain || alert['win.eventdata.domain'] || '',
    sid: alert.win?.eventdata?.usersid || alert['win.eventdata.usersid'] || ''
  }
};

// Normalize MITRE IDs to array
if (typeof result.rule.mitre === 'string') {
  result.rule.mitre = result.rule.mitre.split(',').map(s => s.trim()).filter(Boolean);
} else if (!Array.isArray(result.rule.mitre)) {
  result.rule.mitre = [];
}

// Determine severity color for Slack
let severityColor = '#36a64f'; // Green (low)
if (result.rule.level >= 12) severityColor = '#ff0000'; // Red (critical)
else if (result.rule.level >= 10) severityColor = '#ff8c00'; // Orange (high)
else if (result.rule.level >= 7) severityColor = '#ffd700'; // Yellow (medium)

result.severity_color = severityColor;
result.severity_text = result.rule.level >= 12 ? 'CRITICAL' : result.rule.level >= 10 ? 'HIGH' : result.rule.level >= 7 ? 'MEDIUM' : 'LOW';

return [{ json: result }];

const alert = items[0].json;
const vtResult = items[1]?.json || {};

let vtSummary = 'No hash provided or lookup failed';
let vtMalicious = 0;
let vtSuspicious = 0;
let vtUndetected = 0;
let vtPermalink = '';

if (vtResult.data && vtResult.data.attributes) {
  const stats = vtResult.data.attributes.last_analysis_stats || {};
  vtMalicious = stats.malicious || 0;
  vtSuspicious = stats.suspicious || 0;
  vtUndetected = stats.undetected || 0;
  vtPermalink = `https://www.virustotal.com/gui/file/${alert.file.hash_sha256}`;

  vtSummary = `Malicious: ${vtMalicious} | Suspicious: ${vtSuspicious} | Undetected: ${vtUndetected}`;

  if (vtResult.data.attributes.meaningful_name) {
    vtSummary += ` | File: ${vtResult.data.attributes.meaningful_name}`;
  }
  if (vtResult.data.attributes.type_description) {
    vtSummary += ` | Type: ${vtResult.data.attributes.type_description}`;
  }
} else if (vtResult.error) {
  vtSummary = `VT API Error: ${vtResult.error.message || 'Unknown error'}`;
}

// Determine overall threat level
let threatLevel = 'Unknown';
if (vtMalicious > 5) threatLevel = 'HIGHLY MALICIOUS';
else if (vtMalicious > 0) threatLevel = 'MALICIOUS';
else if (vtSuspicious > 0) threatLevel = 'SUSPICIOUS';
else if (vtUndetected > 0) threatLevel = 'CLEAN/UNDETECTED';

return [{ json: { ...alert, vt_summary: vtSummary, vt_malicious: vtMalicious, vt_suspicious: vtSuspicious, vt_undetected: vtUndetected, vt_permalink: vtPermalink, threat_level: threatLevel } }];

const alert = items[0].json;

const mitreLinks = alert.rule.mitre.map(id => `
  • <https://attack.mitre.org/techniques/${id.replace('.', '/')}|${id}>`).join('') || 'None';

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `🚨 SOC Alert: ${alert.rule.description}`,
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Severity:*\n${alert.severity_text} (Level ${alert.rule.level})` },
      { type: 'mrkdwn', text: `*Agent:*\n${alert.agent.name} (${alert.agent.id})` },
      { type: 'mrkdwn', text: `*Agent IP:*\n${alert.agent.ip}` },
      { type: 'mrkdwn', text: `*Rule ID:*\n${alert.rule.id}` },
      { type: 'mrkdwn', text: `*Event ID:*\n${alert.winlog.event_id} (${alert.winlog.channel})` },
      { type: 'mrkdwn', text: `*Timestamp:*\n${new Date(alert.timestamp).toLocaleString()}` }
    ]
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Process Details*\n• *Name:* \`${alert.process.name || 'N/A'}\`\n• *PID:* ${alert.process.pid || 'N/A'}\n• *Command Line:* \`${alert.process.commandline?.substring(0, 200) || 'N/A'}\`\n• *Parent:* \`${alert.process.parent_name || 'N/A'}\` (PID: ${alert.process.parent_pid || 'N/A'})`
    }
  }
];

if (alert.target.image) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Target Process*\n• *Image:* \`${alert.target.image}\`\n• *PID:* ${alert.target.pid}\n• *Granted Access:* \`${alert.target.granted_access}\``
    }
  });
}

if (alert.file.hash_sha256) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*File Indicators*\n• *SHA256:* \`${alert.file.hash_sha256}\`\n• *Path:* \`${alert.file.path}\`\n• *Size:* ${alert.file.size} bytes`
    }
  });
}

if (alert.network.dst_ip) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Network Indicators*\n• *Protocol:* ${alert.network.protocol}\n• *Source:* ${alert.network.src_ip}:${alert.network.src_port}\n• *Destination:* ${alert.network.dst_ip}:${alert.network.dst_port}`
    }
  });
}

blocks.push({
  type: 'section',
  text: {
    type: 'mrkdwn',
    text: `*VirusTotal Enrichment*\n• *Verdict:* ${alert.threat_level}\n• *Summary:* ${alert.vt_summary}\n• *Link:* ${alert.vt_permalink || 'N/A'}`
  }
});

blocks.push({
  type: 'section',
  text: {
    type: 'mrkdwn',
    text: `*MITRE ATT&CK Techniques*${mitreLinks}`
  }
});

blocks.push({
  type: 'context',
  elements: [
    { type: 'mrkdwn', text: `Alert ID: ${alert.rule.id} | Generated by Wazuh SOAR Pipeline` }
  ]
});

return [{ json: { blocks, color: alert.severity_color } }];
